package app.sleepscreen.tv;
import android.app.Activity;import android.os.Handler;import android.os.Looper;import org.json.*;import java.net.*;import java.io.*;import java.util.function.Consumer;
final class UpdateCheck {
 static final String API="https://api.github.com/repos/spencerkotulski/sleep-screen/releases";
 static void check(Activity a,Consumer<String[]> done){new Thread(()->{String[] result=null;try{HttpURLConnection c=(HttpURLConnection)new URL(API).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","SleepScreen-Android");if(c.getResponseCode()!=200)throw new IOException("GitHub unavailable");ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){b.write(buf,0,n);if(b.size()>1000000)throw new IOException("Response too large");}}JSONArray releases=new JSONArray(b.toString("UTF-8"));String current=a.getPackageManager().getPackageInfo(a.getPackageName(),0).versionName;for(int i=0;i<releases.length();i++){JSONObject rel=releases.getJSONObject(i);if(rel.optBoolean("draft"))continue;String tag=rel.optString("tag_name");if(compare(tag,current)<=0)continue;JSONArray assets=rel.optJSONArray("assets");if(assets==null)continue;for(int j=0;j<assets.length();j++){JSONObject asset=assets.getJSONObject(j);String name=asset.optString("name"),url=asset.optString("browser_download_url");if(name.endsWith(".apk")&&url.startsWith("https://github.com/spencerkotulski/sleep-screen/releases/download/")){result=new String[]{tag,url};break;}}if(result!=null)break;}}catch(Exception ignored){}final String[] out=result;new Handler(Looper.getMainLooper()).post(()->{if(!a.isFinishing()&&!a.isDestroyed())done.accept(out);});}).start();}
 static int compare(String a,String b){String[] x=a.replaceFirst("^[vV]","").split("[-+.]"),y=b.replaceFirst("^[vV]","").split("[-+.]");for(int i=0;i<3;i++){int n=part(x,i),m=part(y,i);if(n!=m)return Integer.compare(n,m);}boolean ap=a.contains("-"),bp=b.contains("-");return ap==bp?0:(ap?-1:1);}private static int part(String[] x,int i){try{return Integer.parseInt(x[i]);}catch(Exception e){return 0;}}
}